head.script:
scwin.vScrenID = "ULDFIS00309.xml";

scwin.onpageload = function() {
    scwin.fn_Init();
};

scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
     scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dlt_OthCorpContrbStatRes.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {

    let ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue() ; 
    let sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 타법인출자현황  조회
 */
scwin.fn_Search = async function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }


    let ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue() ; 
    let sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    let url = "/api/listing/nice/individual-notes/other-corporate-investemnets?kisCd="+ibxKisCd+"&acntclsDt="+sbxAcntclsDt;
    await $c.sbm.setAction(sbm_dlt_OthCorpContrbStat, url);
    await $c.sbm.execute(sbm_dlt_OthCorpContrbStat);

    await scwin.fn_AppendContents(); 
};


/**
 * 컨텐츠 append
 */
scwin.fn_AppendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:600px;font-family:돋움체;'>";
    for (var nRow = 0; nRow <= dlt_OthCorpContrbStatRes.getTotalRow(); nRow++) {
        strContent = strContent + dlt_OthCorpContrbStatRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";
    let grpCtntObj = $p.getComponentById("grp_Ctnt").render;
    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");
};
